export const LINES = Object.freeze({
  exited: 'the helper exited',
  restarted: 'the helper restarted',
  noAnswer: 'the helper did not answer',
  quiet: 'the helper is quiet'
});
const SOLO = 'the helper kept exiting, so it stopped restarting it';
log.warn(`${LINES.exited} (code ${String(code)})`, { code });
log.info(`${LINES.restarted} (generation ${g}, ${n} watches re-bound)`);
log.warn(`${LINES.noAnswer} a ${op} within ${ms} ms, so it was ${outcome}`);
log.warn(SOLO + ' (' + String(n) + ' exits)');
log.info(LINES.quiet);
log.warn(unknownThing);

log.warn('the watcher process exited with ' + String(code) + ', restarting it');
watcherLog.warn(`repo watcher (${repoPath}): ${err.message}`);
log.info("the watcher process stopped answering; replacing it");
